<div class="card"><div class="card-header border-bottom border-dashed"><h4 class="header-title mb-0">Pilih Tagihan</h4></div><div class="card-body"><div class="row g-2 align-items-end"><div class="col-md-6"><label class="form-label">Tagihan</label><select id="tagihan" class="form-select"><option value="">Pilih tagihan</option><?php foreach($tagihan as $r): ?><option value="<?= $r['id'] ?>" <?= $id_tagihan===$r['id']?'selected':'' ?>><?= html_escape($r['periode'].' - '.$r['nama_tagihan'].' ['.$r['status'].']') ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Cari Siswa</label><input id="search" class="form-control" placeholder="Nama/NIS/NISN"></div><div class="col-md-2 d-grid"><button class="btn btn-primary" onclick="loadData()">Tampilkan</button></div></div></div></div>
<div id="content" class="d-none"><div class="row g-3"><div class="col-xl-6"><div class="card"><div class="card-header border-bottom border-dashed d-flex justify-content-between"><h4 class="header-title mb-0">Siswa Pembayar</h4><span class="badge bg-primary" id="count_current">0</span></div><div class="card-body p-0"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Siswa</th><th>Tarif</th><th>Dibayar</th><th>Aksi</th></tr></thead><tbody id="current"></tbody></table></div></div></div></div><div class="col-xl-6"><div class="card"><div class="card-header border-bottom border-dashed d-flex justify-content-between"><h4 class="header-title mb-0">Calon Siswa</h4><div><button class="btn btn-sm btn-light" onclick="$('.candidate').prop('checked',true)">Pilih Semua</button><button class="btn btn-sm btn-primary" id="btn_tambah">Tambah Terpilih</button></div></div><div class="card-body p-0"><div class="table-responsive"><table class="table mb-0"><thead><tr><th width="35"></th><th>Siswa</th><th>Kelas</th></tr></thead><tbody id="candidates"></tbody></table></div></div></div></div></div></div>
<script>
$(function(){$('#tagihan').change(loadData);$('#btn_tambah').click(tambah);$('#search').keyup(function(e){if(e.key==='Enter')loadData();});if($('#tagihan').val())loadData();});
function loadData(){var id=$('#tagihan').val();if(!id)return;$.post('<?= base_url('siswa_pembayar/result') ?>',{id_tagihan:id,search:$('#search').val()},function(r){if(r.result!=='true')return Swal.fire('Gagal',r.message,'error');$('#content').removeClass('d-none');$('#count_current').text(r.current.length);var a='',b='';if(!r.current.length)a='<tr><td colspan="4"><div class="empty-state">Belum ada tagihan siswa.</div></td></tr>';r.current.forEach(function(x){a+='<tr><td><strong>'+escapeHtml(x.nama_siswa)+'</strong><br><small>'+escapeHtml(x.nis)+' | '+escapeHtml(x.nama_kelas)+'</small></td><td>'+formatRupiah(x.tarif)+'</td><td>'+formatRupiah(x.dibayar)+'</td><td><button class="btn btn-sm btn-outline-danger" onclick="keluarkan('+x.id_siswa+')">Keluarkan</button></td></tr>';});if(!r.candidates.length)b='<tr><td colspan="3"><div class="empty-state">Tidak ada calon siswa.</div></td></tr>';r.candidates.forEach(function(x){b+='<tr><td><input type="checkbox" class="form-check-input candidate" value="'+x.id_siswa+'"></td><td><strong>'+escapeHtml(x.nama_siswa)+'</strong><br><small>'+escapeHtml(x.nis)+' / '+escapeHtml(x.nisn)+'</small></td><td>'+escapeHtml(x.nama_kelas)+'</td></tr>';});$('#current').html(a);$('#candidates').html(b);},'json').fail(ajaxError);}
function tambah(){var ids=$('.candidate:checked').map(function(){return this.value;}).get();if(!ids.length)return Swal.fire('Perhatian','Pilih siswa yang akan ditambahkan.','warning');confirmAction('Tambahkan siswa?','Tarif mengikuti tarif khusus, tarif kelas, lalu tarif umum.',function(){$.post('<?= base_url('siswa_pembayar/tambah') ?>',{id_tagihan:$('#tagihan').val(),id_siswa:ids},function(r){Swal.fire(r.result==='true'?'Berhasil':'Gagal',r.message,r.result==='true'?'success':'error');loadData();},'json').fail(ajaxError);});}
function keluarkan(id){confirmAction('Keluarkan siswa?','Siswa yang sudah membayar tidak dapat dikeluarkan.',function(){$.post('<?= base_url('siswa_pembayar/keluarkan') ?>',{id_tagihan:$('#tagihan').val(),id_siswa:id},function(r){Swal.fire(r.result==='true'?'Berhasil':'Gagal',r.message,r.result==='true'?'success':'error');loadData();},'json').fail(ajaxError);});}
</script>
